(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.02-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.25)*20 + Math.sin(x*0.02+t*0.18)*15;
  const w2x = Math.sin((x+w1x)*0.02+t*0.3)*10 + Math.cos((y+w1y)*0.015-t*0.22)*8;
  const w2y = Math.cos((y+w1y)*0.02-t*0.28)*10 + Math.sin((x+w1x)*0.015+t*0.25)*8;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
