  const feed = act - inh*0.7 + bg*0.3 + spiral;
  const reaction = Math.tanh(feed*2.2);
  const diffusion = Math.tanh((act*inh*0.5 + spiral*0.3)*1.8);
  const pattern = reaction*0.7 + diffusion*0.3;
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = pattern*0.8 + cell*0.2, v = blend*0.5+0.5;
